data.nginx.conf:
pid /tmp/nginx.pid;
events {}
http {
 include /etc/nginx/mime.types;
 client_body_temp_path /tmp/client;
 proxy_temp_path /tmp/proxy;
 fastcgi_temp_path /tmp/fastcgi;
 uwsgi_temp_path /tmp/uwsgi;
 scgi_temp_path /tmp/scgi;
 server { listen 8080; root /usr/share/nginx/html;
 add_header X-Content-Type-Options nosniff;
 add_header Content-Security-Policy "default-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com; img-src 'self' data:; script-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'self'; form-action 'self'";
 location /api/ { proxy_pass http://delo-gateway:8080; proxy_set_header Host $host; }
 location / { try_files $uri /index.html; }
 }
}
